            if prev['kind'] == 'pay':
                if prev['amount'] != event['amount']:
                    raise ValueError('id')
            else:
                if prev['payment'] != event['payment'] or prev['amount'] != event['amount']:
                    raise ValueError('id')
            continue

        amount = event['amount']
        if amount <= 0:
            raise ValueError('amount')

        if event['kind'] == 'pay':
            payments[ident] = amount
        else:
            target = event['payment']
            if target not in payments:
                raise ValueError('payment')
            payments[target] += amount

        seen[ident] = event

    rows = []
    for ident in sorted(payments.keys()):
        paid = payments[ident]
        refunded = 0
        for event in events:
            if event['id'] == ident and event['kind'] == 'refund' and event['payment'] == ident:
                refunded += event['amount']
        remaining = paid - refunded
        if remaining < 0:
            raise ValueError('refund')
